def slot_provenance(beat):
    pat = beat['shot']['remotion']['pattern']
    if pat: return 'Brutalist'
    fill = beat['build']['filled_by']
    if fill.startswith(('remotion:','manim:')):
        return 'Brutalist'
    stype = beat['shot']['type']
    if stype in AI_VIDEO_TYPES:
        return 'YOU'
    return 'Capture?'

